window.AUTH=window.AUTH||{};window.AUTH["17-9560"]={"d":"17-9560","id":"2018/17-9560","n":"Rehaif v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Hamid Rehaif","date":"2019-02-22","url":"https://www.supremecourt.gov/DocketPDF/17/17-9560/89331/20190222155834806_17-9560ts.pdf","side":"pet","n":44},{"k":"respondent","label":"Brief of respondent United States","date":"2019-03-25","url":"https://www.supremecourt.gov/DocketPDF/17/17-9560/93150/20190325190401864_17-9560bsUnitedStates.pdf","side":"res","n":140},{"k":"reply","label":"Reply of petitioner Hamid Rehaif","date":"2019-04-12","url":"https://www.supremecourt.gov/DocketPDF/17/17-9560/96293/20190412135543165_17-9560rb.pdf","side":"pet","n":41}],"opinion":"https://www.supremecourt.gov/opinions/18pdf/17-9560_new_onkq.pdf","tr":true,"items":[{"t":"case","label":"Ali v. Fed. Bureau of Prisons","cite":"552 U.S. 214","y":2008,"id":"2007/06-9130","sc":1,"by":{"0":"12"},"q":[{"src":"brief","b":0,"text":"give effect to the text Congress enacted.","cite":"552 U.S. 214, 228"}]},{"t":"case","label":"Almendarez–Torres v. United States","cite":"523 U.S. 224","y":1998,"id":"1997/96-6839","sc":1,"by":{"0":"20"}},{"t":"case","label":"Am. Tobacco Co. v. Patterson","cite":"456 U.S. 63","y":1982,"id":"1981/80-1199","sc":1,"by":{"0":"12"},"q":[{"src":"brief","b":0,"text":"As in all cases involving statutory construction, our starting point must be the language employed by Congress, and we assume that the legislative purpose is expressed by the ordinary meaning of the words used.","cite":"456 U.S. 63, 68"}]},{"t":"case","label":"Cannon v. Univ. of Chi.","cite":"441 U.S. 677","y":1979,"id":"1978/77-926","sc":1,"by":{"0":"22, 23"}},{"t":"case","label":"Cent. Bank of Denver v. First Interstate Bank","cite":"511 U.S. 164","y":1994,"id":"1993/92-854","sc":1,"by":{"0":"24","2":"19"},"q":[{"src":"brief","b":2,"text":"[c]ongressional inaction cannot amend a duly enacted statute.","cite":"511 U.S. 164, 186"}]},{"t":"case","label":"Conn. Nat’l Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"by":{"0":"12"},"q":[{"src":"brief","b":0,"text":"says in a statute what it means and means in a statute what it says there.","cite":"503 U.S. 249, 253-54"}]},{"t":"case","label":"Culbertson v. Berryhill","cite":"139 S. Ct. 517","y":2019,"id":"2018/17-773","sc":1,"by":{"0":"12, 13"}},{"t":"case","label":"Dennis v. United States","cite":"341 U.S. 494","y":1951,"id":"1940-1955/341us494","sc":1,"by":{"0":"24"}},{"t":"case","label":"Elonis v. United States","cite":"135 S. Ct. 2001","y":2015,"id":"2014/13-983","sc":1,"by":{"0":"17, 18","1":"26, 42"},"q":[{"src":"brief","b":1,"text":"to separate wrongful conduct from otherwise innocent conduct,","cite":"135 S. Ct. at 2010"}]},{"t":"case","label":"Flores-Figueroa v. United States","cite":"556 U.S. 646","y":2009,"id":"2008/08-108","sc":1,"by":{"0":"passim","1":"41","2":"3"},"q":[{"src":"brief","b":0,"text":"ignorance of the law is no excuse.","cite":"556 U.S. at 652"},{"src":"brief","b":1,"text":"that introduce[ ] the elements of a crime with the word ‘knowingly.’","cite":"556 U.S. 646, 652"},{"src":"brief","b":1,"text":"assume that an adverb (such as knowingly) that modifies the transitive verb tells the listener how the subject performed the entire action, including the object as set forth in the sentence.","cite":"556 U.S. at 650"},{"src":"opinion","who":"Opinion of the Court (Justice Breyer)","text":"‘knowingly’ as applying to all the subsequently listed elements of the crime.","cite":"556 U. S. 646, 650"}]},{"t":"case","label":"Jennings v. Rodriguez","cite":"138 S. Ct. 830","y":2018,"id":"2017/15-1204","sc":1,"by":{"0":"25"},"q":[{"src":"brief","b":0,"text":"when statutory language is susceptible of multiple interpretations, a court may shun an interpretation that raises serious constitutional doubts and instead may adopt an alternative that avoids those problems.","cite":"138 S. Ct. 830, 836"}]},{"t":"case","label":"Liparota v. United States","cite":"471 U.S. 419","y":1985,"id":"1984/84-5108","sc":1,"by":{"0":"passim","1":"41","2":"1, 12"},"q":[{"src":"brief","b":0,"text":"Application of the rule of lenity ensures that criminal statutes will provide fair warning concerning conduct rendered illegal and strikes the appropriate balance between the legislature, the prosecutor, and the court in defining criminal liability.","cite":"471 U.S. at 427"}]},{"t":"case","label":"Morissette v. United States","cite":"342 U.S. 246","y":1952,"id":"scdb/1951-028","sc":1,"by":{"0":"9, 18, 27","1":"15"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Breyer)","text":"is as universal and persistent in mature systems of law as belief in freedom of the human will and a consequent ability and duty of the normal individual to choose between good and evil.","cite":"342 U. S., at 250"},{"src":"argument","who":"Justice Kavanaugh","text":"Mistake of fact has always been recognized as a defense, or, put conversely, knowledge has always been required -- going back to Justice Jackson in Morissette and all through the cases, as required for all the elements of the offense."},{"src":"argument","who":"Justice Gorsuch","text":"Well, let -- let me -- let me ask you, just to -- just to follow up on Rob -- since Robert Jackson's name's been invoked here, Morissette, \"the contention that an injury can amount to a crime only when inflicted by intention is no provincial or transient notion."},{"src":"argument","who":"Justice Kavanaugh","text":"So Morissette itself, the charge was converting government property. And the defendant's argument was I didn't think it was government property because I thought it was abandoned."}]},{"t":"case","label":"Pa. Dep’t Pub. Welfare v. Davenport","cite":"495 U.S. 552","y":1990,"id":"1989/89-156","sc":1,"by":{"0":"22"}},{"t":"case","label":"Rodriguez v. United States","cite":"480 U.S. 522","y":1987,"id":"1986/86-5504","sc":1,"by":{"0":"34","2":"19"},"q":[{"src":"brief","b":0,"text":"it frustrates rather than effectuates legislative intent simplistically to assume that whatever furthers the statute’s primary objective must be law.","cite":"480 U.S. 522, 526"},{"src":"brief","b":2,"text":"it frustrates rather than effectuates legislative intent simplistically to assume that whatever furthers the statute’s primary objective must be the law.","cite":"480 U.S. 522, 526"}]},{"t":"case","label":"Staples v. United States","cite":"511 U.S. 600","y":1994,"id":"1993/92-1441","sc":1,"by":{"0":"12, 17, 26","1":"21, 43, 44, 45","2":"9, 10, 19, 20, 21"},"q":[{"src":"brief","b":0,"text":"dispens[e] with mens rea [when doing so] would require the defendant to have knowledge only of traditionally lawful conduct.","cite":"511 U.S. at 618"},{"src":"brief","b":1,"text":"different elements of the same offense can require different mental states,","cite":"511 U.S. 600, 609"},{"src":"brief","b":1,"text":"simple transaction[s] that would not alert a person to regulation any more than would buying a car.","cite":"511 U.S. at 614"},{"src":"brief","b":2,"text":"long tradition of widespread lawful gun ownership by private individuals in this country.","cite":"511 U.S. at 610"},{"src":"argument","who":"Justice Sotomayor","text":"Well, I guess my question becomes, what do we do with the Staples presumption?"}]},{"t":"case","label":"Torres v. Lynch","cite":"136 S. Ct. 1619","y":2016,"url":"https://www.courtlistener.com/c/S.%20Ct./136/1619/","sc":1,"by":{"0":"31","1":"21","2":"3"},"q":[{"src":"brief","b":0,"text":"the jurisdictional element [that] connects the law to one of Congress’s enumerated powers, thus establishing legislative authority.","cite":"136 S. Ct. 1619, 1630"}]},{"t":"case","label":"United States v. Feola","cite":"420 U.S. 671","y":1975,"id":"1974/73-1123","sc":1,"by":{"0":"31, 32","2":"4"}},{"t":"case","label":"United States v. Games-Perez","cite":"667 F.3d 1136","y":2012,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/667/1136/","by":{"0":"13, 14, 17, 18","1":"32","2":"passim"},"q":[{"src":"brief","b":0,"text":"a perfectly clear law as it is written, plain in its terms, straightforward in its application.","cite":"667 F.3d 1136, 1145"},{"src":"brief","b":0,"text":"defies linguistic sense – and not a little grammatical gravity.","cite":"667 F.3d 1136, 1143"}]},{"t":"case","label":"United States v. Games-Perez","cite":"695 F.3d 1104","y":2012,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/695/1104/","by":{"0":"14, 23, 25, 26","2":"16"},"q":[{"src":"brief","b":0,"text":"[T]he law before us that survived the gauntlet of bicameralism and presentment couldn’t be plainer. By their express terms, §§ 922(g) and 924(a)(2) do not authorize the government to imprison [persons] unless and until the government can show they knew of their felon status at the time of the alleged offense.","cite":"695 F.3d 1104, 1118"},{"src":"brief","b":0,"text":"Whatever weight courts may give to judicial interpretations of predecessor statutes when the current statute is ambiguous, those prior interpretations of now defunct statutes carry no weight when the language of the current statute is clear.","cite":"695 F.3d at 1118"}]},{"t":"case","label":"United States v. Int’l Minerals & Chem. Corp.","cite":"402 U.S. 558","y":1971,"id":"1970/557","sc":1,"by":{"0":"20","1":"23"}},{"t":"case","label":"United States v. Kozminski","cite":"487 U.S. 931","y":1988,"id":"1987/86-2000","sc":1,"by":{"0":"30"},"q":[{"src":"brief","b":0,"text":"[t]he purposes underlying the rule of lenity—to promote fair notice to those subject to the criminal laws, to minimize the risk of selective or arbitrary enforcement, and to maintain the proper balance between Congress, prosecutors, and courts— are certainly served by its application in this case.","cite":"487 U.S. 931, 952"}]},{"t":"case","label":"United States v. Langley","cite":"62 F.3d 602","y":1995,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/62/602/","by":{"0":"22, 23, 24","1":"32"},"q":[{"src":"brief","b":0,"text":"that, unless statutory language or legislative history evinces a contrary intent, a nonspecific mens rea requirement was intended by Congress to run to ‘each of the statutory elements which criminalize otherwise innocent behavior.’","cite":"62 F.3d at 614"},{"src":"brief","b":0,"text":"the Supreme Court’s application of the common law presumption of an intent to give scienter requirements their broadest possible reach (i.e., to all elements, including criminalizing ‘facts and circumstances’) must be accorded primacy as interpretive guide.","cite":"62 F.3d at 618"}]},{"t":"case","label":"United States v. Pruner","cite":"606 F.2d 871","y":1979,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/606/871/","by":{"0":"21","1":"30"}},{"t":"case","label":"United States v. Renner","cite":"496 F.2d 922","y":1974,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/496/922/","by":{"0":"25","1":"31"}},{"t":"case","label":"United States v. Ruisi","cite":"460 F.2d 153","y":1972,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/460/153/","by":{"0":"21"}},{"t":"case","label":"United States v. Turkette","cite":"452 U.S. 576","y":1981,"id":"1980/80-808","sc":1,"by":{"0":"20"}},{"t":"case","label":"United States v. U.S. Gypsum Co.","cite":"438 U.S. 422","y":1978,"id":"1977/76-1560","sc":1,"by":{"0":"24","1":"44","2":"21"},"q":[{"src":"brief","b":1,"text":"do not invariably offend constitutional requirements.","cite":"438 U.S. 422, 437"}]},{"t":"case","label":"United States v. Ware","cite":"758 F.2d 557","y":1985,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/758/557/","by":{"0":"21"}},{"t":"case","label":"United States v. X-Citement Video, Inc.","cite":"513 U.S. 64","y":1994,"id":"1994/93-723","sc":1,"by":{"0":"passim","1":"41","2":"9"},"q":[{"src":"brief","b":0,"text":"the crucial element separating legal innocence from wrongful conduct,","cite":"513 U.S. at 73"},{"src":"brief","b":0,"text":"presumption in favor of a scienter requirement should apply to each of the statutory elements that criminalize otherwise innocent conduct.","cite":"513 U.S. at 72"},{"src":"brief","b":2,"text":"scienter requirement should apply to each of the statutory elements that criminalize otherwise innocent conduct.","cite":"513 U.S. 64, 72"},{"src":"opinion","who":"Opinion of the Court (Justice Breyer)","text":"separate those who understand the wrongful nature of their act from those who do not.","cite":"513 U. S., at 72"},{"src":"opinion","who":"Opinion of the Court (Justice Breyer)","text":"the most grammatical reading of the statute","cite":"513 U. S., at 70"},{"src":"argument","who":"Justice Gorsuch","text":"And -- and we've got X-Citement Video as well. So if, you know --"}]},{"t":"case","label":"Washington v. Glucksberg","cite":"521 U.S. 702","y":1997,"id":"1996/96-110","sc":1,"by":{"0":"27, 28"},"q":[{"src":"brief","b":0,"text":"specially protects those fundamental rights and liberties, which are, objectively, ‘deeply rooted in this Nation’s history and tradition.’","cite":"521 U.S. 702, 720-21"}]},{"t":"case","label":"Wirtz v. Local 153, Bottle Blowers Ass’n","cite":"389 U.S. 463","y":1968,"id":"1967/57","sc":1,"by":{"0":"19, 20"}},{"t":"case","label":"Yates v. United States","cite":"135 S. Ct. 1074","y":2015,"id":"2014/13-7451","sc":1,"by":{"0":"28","2":"21"},"q":[{"src":"brief","b":0,"text":"invoke[s] the rule that ‘ambiguity concerning the ambit of criminal statutes should be resolved in favor of lenity.’","cite":"135 S. Ct. 1074, 1088"}]},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"0":"1"}},{"t":"usc","label":"18 U.S.C. § 922","url":"https://www.law.cornell.edu/uscode/text/18/922","subs":["(g)","(d)","(d)(5)(A)","(g)(1)","(g)(2)","(g)(3)","(g)(4)","(g)(5)","(g)(5)(A)","(g)(7)","(g)(8)(A)","(g)(9)","(h)","(i)"],"stext":{"head":"§922. Unlawful acts","paras":[[0,"(a) It shall be unlawful—"],[1,"(1) for any person—"],[2,"(A) except a licensed importer, licensed manufacturer, or licensed dealer, to engage in the business of importing, manufacturing, or dealing in firearms, or in the course of such business to ship, transport, or receive any firearm in interstate or foreign commerce; or"],[2,"(B) except a licensed importer or licensed manufacturer, to engage in the business of importing or manufacturing ammunition, or in the course of such business, to ship, transport, or receive any ammunition in interstate or foreign commerce;"],[1,"(2) for any importer, manufacturer, dealer, or collector licensed under the provisions of this chapter to ship or transport in interstate or foreign commerce any firearm to any person other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, except that—"],[2,"(A) this paragraph and subsection (b)(3) shall not be held to preclude a licensed importer, licensed manufacturer, licensed dealer, or licensed collector from returning a firearm or replacement firearm of the same kind and type to a person from whom it was received; and this paragraph shall not be held to preclude an individual from mailing a firearm owned in compliance with Federal, State, and local law to a licensed importer, licensed manufacturer, licensed dealer, or licensed collector;"],[2,"(B) this paragraph shall not be held to preclude a licensed importer, licensed manufacturer, or licensed dealer from depositing a firearm for conveyance in the mails to any officer, employee, agent, or watchman who, pursuant to the provisions of section 1715 of this title, is eligible to receive through the mails pistols, revolvers, and other firearms capable of being concealed on the person, for use in connection with his official duty; and"],[2,"(C) nothing in this paragraph shall be construed as applying in any manner in the District of Columbia, the Commonwealth of Puerto Rico, or any possession of the United States differently than it would apply if the District of Columbia, the Commonwealth of Puerto Rico, or the possession were in fact a State of the United States;"],[1,"(3) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector to transport into or receive in the State where he resides (or if the person is a corporation or other business entity, the State where it maintains a place of business) any firearm purchased or otherwise obtained by such person outside that State, except that this paragraph (A) shall not preclude any person who lawfully acquires a firearm by bequest or intestate succession in a State other than his State of residence from transporting the firearm into or receiving it in that State, if it is lawful for such person to purchase or possess such firearm in that State, (B) shall not apply to the transportation or receipt of a firearm obtained in conformity with subsection (b)(3) of this section, and (C) shall not apply to the transportation of any firearm acquired in any State prior to the effective date of this chapter;"],[1,"(4) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, to transport in interstate or foreign commerce any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity;"],[1,"(5) for any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) to transfer, sell, trade, give, transport, or deliver any firearm to any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) who the transferor knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the transferor resides; except that this paragraph shall not apply to (A) the transfer, transportation, or delivery of a firearm made to carry out a bequest of a firearm to, or an acquisition by intestate succession of a firearm by, a person who is permitted to acquire or possess a firearm under the laws of the State of his residence, and (B) the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(6) for any person in connection with the acquisition or attempted acquisition of any firearm or ammunition from a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, knowingly to make any false or fictitious oral or written statement or to furnish or exhibit any false, fictitious, or misrepresented identification, intended or likely to deceive such importer, manufacturer, dealer, or collector with respect to any fact material to the lawfulness of the sale or other disposition of such firearm or ammunition under the provisions of this chapter;"],[1,"(7) for any person to manufacture or import armor piercing ammunition, unless—"],[2,"(A) the manufacture of such ammunition is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) the manufacture of such ammunition is for the purpose of exportation; or"],[2,"(C) the manufacture or importation of such ammunition is for the purpose of testing or experimentation and has been authorized by the Attorney General;"],[1,"(8) for any manufacturer or importer to sell or deliver armor piercing ammunition, unless such sale or delivery—"],[2,"(A) is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) is for the purpose of exportation; or"],[2,"(C) is for the purpose of testing or experimentation and has been authorized by the Attorney General; 1"],[1,"(9) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, who does not reside in any State to receive any firearms unless such receipt is for lawful sporting purposes."],[0,"(b) It shall be unlawful for any licensed importer, licensed manufacturer, licensed dealer, or licensed collector to sell or deliver—"],[1,"(1) any firearm or ammunition to any individual who the licensee knows or has reasonable cause to believe is less than eighteen years of age, and, if the firearm, or ammunition is other than a shotgun or rifle, or ammunition for a shotgun or rifle, to any individual who the licensee knows or has reasonable cause to believe is less than twenty-one years of age;"],[1,"(2) any firearm to any person in any State where the purchase or possession by such person of such firearm would be in violation of any State law or any published ordinance applicable at the place of sale, delivery or other disposition, unless the licensee knows or has reasonable cause to believe that the purchase or possession would not be in violation of such State law or such published ordinance;"],[1,"(3) any firearm to any person who the licensee knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the licensee's place of business is located, except that this paragraph (A) shall not apply to the sale or delivery of any rifle or shotgun to a resident of a State other than a State in which the licensee's place of business is located if the transferee meets in person with the transferor to accomplish the transfer, and the sale, delivery, and receipt fully comply with the legal conditions of sale in both such States (and any licensed manufacturer, importer or dealer shall be presumed, for purposes of this subparagraph, in the absence of evidence to the contrary, to have had actual knowledge of the State laws and published ordinances of both States), and (B) shall not apply to the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(4) to any person any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity; and"],[1,"(5) any firearm or armor-piercing ammunition to any person unless the licensee notes in his records, required to be kept pursuant to section 923 of this chapter, the name, age, and place of residence of such person if the person is an individual, or the identity and principal and local places of business of such person if the person is a corporation or other business entity."],[0,"Paragraphs (1), (2), (3), and (4) of this subsection shall not apply to transactions between licensed importers, licensed manufacturers, licensed dealers, and licensed collectors. Paragraph (4) of this subsection shall not apply to a sale or delivery to any research organization designated by the Attorney General."],[0,"(c) In any case not otherwise prohibited by this chapter, a licensed importer, licensed manufacturer, or licensed dealer may sell a firearm to a person who does not appear in person at the licensee's business premises (other than another licensed importer, manufacturer, or dealer) only if—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/922?type=usc&year=mostrecent&link-type=html"},"by":{"0":"passim","1":"19, 19, 19, 19, 19, 19, 19, 19, 19, 19, 19, 19, 19, 19, 19, 19","2":"passim, 6"},"q":[{"src":"brief","b":1,"text":"any person * * * who has been convicted in any court of, a crime punishable by imprisonment for a term exceeding one year,","cite":"18 U.S.C. 922(g)(1)"},{"src":"brief","b":1,"text":"any person * * * who, being an alien * * * (A) is illegally or unlawfully in the United States; or (B) [with certain exceptions] has been admitted to the United States under a nonimmigrant visa,","cite":"18 U.S.C. 922(g)(5)"},{"src":"opinion","who":"Opinion of the Court (Justice Breyer)","text":"Whoever knowingly violates subsection (a)(6), (d), (g), (h), (i), (j), or (o) of section 922 shall be fined as provided in this title, imprisoned not more than 10 years, or both.","cite":"18 U. S. C. §922(g)"}]},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(a)(2)","(e)(1)","(2012)","(a)","(a)(1)","(a)(1)(B)","(a)(1)(D)"],"stext":{"head":"§924. Penalties","paras":[[0,"(a)(1) Except as otherwise provided in this subsection, subsection (b), (c), (f), or (p) of this section, or in section 929, whoever—"],[1,"(A) knowingly makes any false statement or representation with respect to the information required by this chapter to be kept in the records of a person licensed under this chapter or in applying for any license or exemption or relief from disability under the provisions of this chapter;"],[1,"(B) knowingly violates subsection (a)(4), (f), (k), or (q) of section 922;"],[1,"(C) knowingly imports or brings into the United States or any possession thereof any firearm or ammunition in violation of section 922(l); or"],[1,"(D) willfully violates any other provision of this chapter,"],[0,"shall be fined under this title, imprisoned not more than five years, or both."],[0,"(2) Whoever knowingly violates subsection (a)(6), (h), (i), (j), or (o) of section 922 shall be fined as provided in this title, imprisoned not more than 10 years, or both."],[0,"(3) Any licensed dealer, licensed importer, licensed manufacturer, or licensed collector who knowingly—"],[1,"(A) makes any false statement or representation with respect to the information required by the provisions of this chapter to be kept in the records of a person licensed under this chapter, or"],[1,"(B) violates subsection (m) of section 922,"],[0,"shall be fined under this title, imprisoned not more than one year, or both."],[0,"(4) Whoever violates section 922(q) shall be fined under this title, imprisoned for not more than 5 years, or both. Notwithstanding any other provision of law, the term of imprisonment imposed under this paragraph shall not run concurrently with any other term of imprisonment imposed under any other provision of law. Except for the authorization of a term of imprisonment of not more than 5 years made in this paragraph, for the purpose of any other law a violation of section 922(q) shall be deemed to be a misdemeanor."],[0,"(5) Whoever knowingly violates subsection (s) or (t) of section 922 shall be fined under this title, imprisoned for not more than 1 year, or both."],[0,"(6)(A)(i) A juvenile who violates section 922(x) shall be fined under this title, imprisoned not more than 1 year, or both, except that a juvenile described in clause (ii) shall be sentenced to probation on appropriate conditions and shall not be incarcerated unless the juvenile fails to comply with a condition of probation."],[0,"(ii) A juvenile is described in this clause if—"],[1,"(I) the offense of which the juvenile is charged is possession of a handgun or ammunition in violation of section 922(x)(2); and"],[1,"(II) the juvenile has not been convicted in any court of an offense (including an offense under section 922(x) or a similar State law, but not including any other offense consisting of conduct that if engaged in by an adult would not constitute an offense) or adjudicated as a juvenile delinquent for conduct that if engaged in by an adult would constitute an offense."],[0,"(B) A person other than a juvenile who knowingly violates section 922(x)—"],[1,"(i) shall be fined under this title, imprisoned not more than 1 year, or both; and"],[1,"(ii) if the person sold, delivered, or otherwise transferred a handgun or ammunition to a juvenile knowing or having reasonable cause to know that the juvenile intended to carry or otherwise possess or discharge or otherwise use the handgun or ammunition in the commission of a crime of violence, shall be fined under this title, imprisoned not more than 10 years, or both."],[0,"(7) Whoever knowingly violates section 931 shall be fined under this title, imprisoned not more than 3 years, or both."],[0,"(8) Whoever knowingly violates subsection (d) or (g) of section 922 shall be fined under this title, imprisoned for not more than 15 years, or both."],[0,"(b) Whoever, with intent to commit therewith an offense punishable by imprisonment for a term exceeding one year, or with knowledge or reasonable cause to believe that an offense punishable by imprisonment for a term exceeding one year is to be committed therewith, ships, transports, or receives a firearm or any ammunition in interstate or foreign commerce shall be fined under this title, or imprisoned not more than ten years, or both."],[0,"(c)(1)(A) Except to the extent that a greater minimum sentence is otherwise provided by this subsection or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries a firearm, or who, in furtherance of any such crime, possesses a firearm, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime—"],[1,"(i) be sentenced to a term of imprisonment of not less than 5 years;"],[1,"(ii) if the firearm is brandished, be sentenced to a term of imprisonment of not less than 7 years; and"],[1,"(iii) if the firearm is discharged, be sentenced to a term of imprisonment of not less than 10 years."],[0,"(B) If the firearm possessed by a person convicted of a violation of this subsection—"],[1,"(i) is a short-barreled rifle, short-barreled shotgun, or semiautomatic assault weapon, the person shall be sentenced to a term of imprisonment of not less than 10 years; or"],[1,"(ii) is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, the person shall be sentenced to a term of imprisonment of not less than 30 years."],[0,"(C) In the case of a violation of this subsection that occurs after a prior conviction under this subsection has become final, the person shall—"],[1,"(i) be sentenced to a term of imprisonment of not less than 25 years; and"],[1,"(ii) if the firearm involved is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, be sentenced to imprisonment for life."],[0,"(D) Notwithstanding any other provision of law—"],[1,"(i) a court shall not place on probation any person convicted of a violation of this subsection; and"],[1,"(ii) no term of imprisonment imposed on a person under this subsection shall run concurrently with any other term of imprisonment imposed on the person, including any term of imprisonment imposed for the crime of violence or drug trafficking crime during which the firearm was used, carried, or possessed."],[0,"(2) For purposes of this subsection, the term \"drug trafficking crime\" means any felony punishable under the Controlled Substances Act (21 U.S.C. 801 et seq.), the Controlled Substances Import and Export Act (21 U.S.C. 951 et seq.), or chapter 705 of title 46."],[0,"(3) For purposes of this subsection the term \"crime of violence\" means an offense that is a felony and—"],[1,"(A) has as an element the use, attempted use, or threatened use of physical force against the person or property of another, or"],[1,"(B) that by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense."],[0,"(4) For purposes of this subsection, the term \"brandish\" means, with respect to a firearm, to display all or part of the firearm, or otherwise make the presence of the firearm known to another person, in order to intimidate that person, regardless of whether the firearm is directly visible to that person."],[0,"(5) Except to the extent that a greater minimum sentence is otherwise provided under this subsection, or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries armor piercing ammunition, or who, in furtherance of any such crime, possesses armor piercing ammunition, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime or conviction under this section—"],[1,"(A) be sentenced to a term of imprisonment of not less than 15 years; and"],[1,"(B) if death results from the use of such ammunition—"],[2,"(i) if the killing is murder (as defined in section 1111), be punished by death or sentenced to a term of imprisonment for any term of years or for life; and"],[2,"(ii) if the killing is manslaughter (as defined in section 1112), be punished as provided in section 1112."],[0,"(d)(1) Any firearm or ammunition involved in or used in any knowing violation of subsection (a)(4), (a)(6), (f), (g), (h), (i), (j), or (k) of section 922, or knowing importation or bringing into the United States or any possession thereof any firearm or ammunition in violation of section 922(l), or knowing violation of section 924, 932, or 933, or willful violation of any other provision of this chapter or any rule or regulation promulgated thereunder, or any violation of any other criminal law of the United States, or any firearm or ammunition intended to be used in any offense referred to in paragraph (3) of this subsection, where such intent is demonstrated by clear and convincing evidence, shall be subject to seizure and forfeiture, and all provisions of the Internal Revenue Code of 1986 relating to the seizure, forfeiture, and disposition of firearms, as defined in section 5845(a) of that Code, shall, so far as applicable, extend to seizures and forfeitures under the provisions of this chapter: Provided, That upon acquittal of the owner or possessor, or dismissal of the charges against him other than upon motion of the Government prior to trial, or lapse of or court termination of the restraining order to which he is subject, the seized or relinquished firearms or ammunition shall be returned forthwith to the owner or possessor or to a person delegated by the owner or possessor unless the return of the firearms or ammunition would place the owner or possessor or his delegate in violation of law. Any action or proceeding for the forfeiture of firearms or ammunition shall be commenced within one hundred and twenty days of such seizure."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/924?type=usc&year=mostrecent&link-type=html"},"by":{"0":"passim","1":"14, 41, 42, 19, 19, 19, 19, 9, 14, 20, 30","2":"passim"},"q":[{"src":"brief","b":1,"text":"shall be fined as provided in this title, imprisoned not more than 10 years, or both.","cite":"18 U.S.C. 924(a)(2)"},{"src":"brief","b":1,"text":"willfully violates any other provision of this chapter,","cite":"18 U.S.C. 924(a)(1)(D)"}]},{"t":"usc","label":"18 U.S.C. § 1751","url":"https://www.law.cornell.edu/uscode/text/18/1751","subs":["(j)"],"by":{"0":"24"}},{"t":"usc","label":"18 U.S.C. § 2241","url":"https://www.law.cornell.edu/uscode/text/18/2241","subs":["(c)","(d)"],"by":{"0":"13, 13"}},{"t":"usc","label":"18 U.S.C. § 2243","url":"https://www.law.cornell.edu/uscode/text/18/2243","subs":["(a)","(d)"],"by":{"0":"24, 24"},"q":[{"src":"brief","b":0,"text":"the Government need not prove that the defendant knew – (1) the age of the other person engaging in the sexual act; or (2) that the requisite age difference existed between the persons so engaging.","cite":"18 U.S.C. §§ 2243(a)"}]},{"t":"law","label":"Firearm Owners’ Protection Act, Pub. L. No. 99-308","url":"https://www.govinfo.gov/link/statute/100/449","by":{"0":"20, 21","1":"31","2":"4"}},{"t":"law","label":"Pub. L. No. 90-351","url":"https://www.govinfo.gov/link/statute/82/225","by":{"0":"20"}},{"t":"law","label":"Pub. L. No. 90-618","url":"https://www.govinfo.gov/link/statute/82/1223","by":{"0":"20"}},{"t":"case","label":"Abramski v. United States","cite":"573 U.S. 169","y":2014,"id":"2013/12-1493","sc":1,"by":{"1":"35, 36, 45"},"q":[{"src":"brief","b":1,"text":"establishes a detailed scheme to enable the dealer to verify, at the point of sale, whether a potential buyer may lawfully own a gun.","cite":"573 U.S. 169, 172"}]},{"t":"case","label":"Barrett v. United States","cite":"423 U.S. 212","y":1976,"id":"1975/74-5566","sc":1,"by":{"1":"16"},"q":[{"src":"brief","b":1,"text":"the persons Congress classified as potentially irresponsible and dangerous * * * are comprehensively barred by the [statute] from acquiring firearms by any means.","cite":"423 U.S. 212, 218"}]},{"t":"case","label":"Boyce Motor Lines, Inc. v. United States","cite":"342 U.S. 337","y":1952,"id":"scdb/1951-035","sc":1,"by":{"1":"23"}},{"t":"case","label":"Braswell v. United States","cite":"224 F.2d 706","y":1955,"url":"https://www.courtlistener.com/c/F.2d/224/706/","by":{"1":"30"}},{"t":"case","label":"Bryan v. United States","cite":"524 U.S. 184","y":1998,"id":"1997/96-8422","sc":1,"by":{"1":"19, 20, 21","2":"5, 11"},"q":[{"src":"brief","b":1,"text":"the background presumption that every citizen knows the law makes it unnecessary to adduce specific evidence to prove that ‘an evil-meaning mind’ directed the ‘evil-doing hand.’","cite":"524 U.S. 184, 193"},{"src":"brief","b":1,"text":"unless the text of the statute dictates a different result, the term ‘knowingly’ merely requires proof of knowledge of the facts that constitute the offense.","cite":"524 U.S. at 193"},{"src":"brief","b":2,"text":"to add a scienter requirement as a condition to the imposition of penalties","cite":"524 U.S. 184, 188"},{"src":"argument","who":"Mr. Kedem","text":"\"Specific acts or omissions\" is a direct quote. And this Court relied on the same understanding more recently in the Bryan case, which construed a different subsection of 924(a)."}]},{"t":"case","label":"Cheek v. United States","cite":"498 U.S. 192","y":1991,"id":"1990/89-658","sc":1,"by":{"1":"19, 20"},"q":[{"src":"brief","b":1,"text":"deeply rooted in the American legal system.","cite":"498 U.S. 192, 199"},{"src":"brief","b":1,"text":"Based on the notion that the law is definite and knowable, the common law presumed that every person knew the law.","cite":"498 U.S. at 199"}]},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"by":{"1":"22","2":"21"}},{"t":"case","label":"Dickerson v. New Banner Inst., Inc.","cite":"460 U.S. 103","y":1983,"id":"1982/81-1180","sc":1,"by":{"1":"16"},"q":[{"src":"brief","b":1,"text":"to keep guns out of the hands of those who have demonstrated that they may not be trusted to possess a firearm without becoming a threat to society.","cite":"460 U.S. 103, 112"}]},{"t":"case","label":"Dixon v. United States","cite":"548 U.S. 1","y":2006,"id":"2005/05-7053","sc":1,"by":{"1":"20"},"q":[{"src":"brief","b":1,"text":"[T]he term ‘willfully’ in § 924(a)(1)(D) requires a defendant to have ‘acted with knowledge that his conduct was unlawful.’","cite":"548 U.S. 1, 5"}]},{"t":"case","label":"Edmonson v. Leesville Concrete Co.","cite":"500 U.S. 614","y":1991,"id":"1990/89-7743","sc":1,"by":{"1":"25"}},{"t":"case","label":"Evans v. United States","cite":"504 U.S. 255","y":1992,"id":"1991/90-6105","sc":1,"by":{"1":"34"}},{"t":"case","label":"Hamling v. United States","cite":"418 U.S. 87","y":1974,"id":"1973/73-507","sc":1,"by":{"1":"23","2":"13"}},{"t":"case","label":"Head v. Hargrave","cite":"105 U.S. 45","y":1881,"id":"scdb/1881-157","sc":1,"by":{"1":"37"}},{"t":"case","label":"Huddleston v. United States","cite":"415 U.S. 814","y":1974,"id":"1973/72-1076","sc":1,"by":{"1":"16"}},{"t":"case","label":"Landsdown v. United States","cite":"348 F.2d 405","y":1965,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/348/405/","by":{"1":"30"}},{"t":"case","label":"Lewis v. United States","cite":"445 U.S. 55","y":1980,"id":"1979/78-1595","sc":1,"by":{"1":"16"}},{"t":"case","label":"Loughrin v. United States","cite":"134 S. Ct. 2384","y":2014,"id":"2013/13-316","sc":1,"by":{"1":"17"}},{"t":"case","label":"Muscarello v. United States","cite":"524 U.S. 125","y":1998,"id":"1997/96-1654","sc":1,"by":{"1":"45"},"q":[{"src":"brief","b":1,"text":"sufficient to warrant application of that rule,","cite":"524 U.S. at 138"},{"src":"brief","b":1,"text":"can make no more than a guess as to what Congress intended.","cite":"524 U.S. at 138"},{"src":"opinion","who":"Justice Alito, dissenting","text":"only if, after seizing everything from which aid can be derived, we can make no more than a guess as to what Congress intended.","cite":"524 U. S. 125, 138"}]},{"t":"case","label":"NLRB v. SW Gen., Inc.","cite":"137 S. Ct. 929","y":2017,"id":"2016/15-1251","sc":1,"by":{"1":"43"},"q":[{"src":"brief","b":1,"text":"floor statements by individual legislators rank among the least illuminating forms of legislative history.","cite":"137 S. Ct. 929, 943"}]},{"t":"case","label":"Neder v. United States","cite":"527 U.S. 1","y":1999,"id":"1998/97-1985","sc":1,"by":{"1":"46","2":"21"}},{"t":"case","label":"Old Chief v. United States","cite":"519 U.S. 172","y":1997,"id":"1996/95-6556","sc":1,"by":{"1":"passim","2":"1, 2, 14, 15"},"q":[{"src":"brief","b":1,"text":"an element entirely outside the natural sequence of what the defendant is charged with thinking and doing to commit the current offense.","cite":"519 U.S. at 191"},{"src":"brief","b":1,"text":"seemingly conclusive evidence of the [prior-conviction] element","cite":"519 U.S. at 186"}]},{"t":"case","label":"Parker v. Matthews","cite":"567 U.S. 37","y":2012,"id":"2011/11-845","sc":1,"by":{"1":"37"}},{"t":"case","label":"Regalado Cuellar v. United States","cite":"553 U.S. 550","y":2008,"id":"2007/06-1456","sc":1,"by":{"1":"36"}},{"t":"case","label":"Robers v. United States","cite":"572 U.S. 639","y":2014,"id":"2013/12-9012","sc":1,"by":{"1":"19"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"by":{"1":"17, 20","2":"6"},"q":[{"src":"brief","b":1,"text":"Where Congress includes particular language in one section of a statute but omits it in another section of the same Act, it is generally presumed that Congress acts intentionally and purposely in the disparate inclusion or exclusion.","cite":"464 U.S. 16, 23"}]},{"t":"case","label":"Small v. United States","cite":"544 U.S. 385","y":2005,"id":"2004/03-750","sc":1,"by":{"1":"16"}},{"t":"case","label":"Smith v. United States","cite":"508 U.S. 223","y":1993,"id":"1992/91-8674","sc":1,"by":{"1":"45"},"q":[{"src":"brief","b":1,"text":"[t]he mere possibility of articulating a narrower construction,","cite":"508 U.S. 223, 239"}]},{"t":"case","label":"United States v. Bishop","cite":"412 U.S. 346","y":1973,"id":"1972/71-1698","sc":1,"by":{"1":"20"},"q":[{"src":"brief","b":1,"text":"intentional violation of a known legal duty.","cite":"412 U.S. 346, 360"},{"src":"opinion","who":"Justice Alito, dissenting","text":"intentional violation of a known legal duty.","cite":"412 U. S. 346, 360"}]},{"t":"case","label":"United States v. Bryant","cite":"523 F.3d 349","y":2008,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/523/349/","by":{"1":"33"}},{"t":"case","label":"United States v. Capps","cite":"77 F.3d 350","y":1996,"url":"https://www.courtlistener.com/c/F.3d/77/350/","by":{"1":"32"},"q":[{"src":"argument","who":"Justice Gorsuch","text":"-- counsel, you talk about this -- this prior history as if it were handed to us on tablets, but the -- the only prior history I'm aware of really is that Fourth Circuit opinion, Capps, and it -- it seems to rely on a very convoluted parsing of the legislative history of a predecessor statute."}]},{"t":"case","label":"United States v. Castleman","cite":"572 U.S. 157","y":2014,"id":"2013/12-1371","sc":1,"by":{"1":"46"}},{"t":"case","label":"United States v. Chin","cite":"981 F.2d 1275","y":1992,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/981/1275/","by":{"1":"23","2":"10"}},{"t":"case","label":"United States v. Dancy","cite":"861 F.2d 77","y":1988,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/861/77/","by":{"1":"32"}},{"t":"case","label":"United States v. Freed","cite":"401 U.S. 601","y":1971,"id":"1970/345","sc":1,"by":{"1":"44","2":"21"}},{"t":"case","label":"United States v. Goodie","cite":"524 F.2d 515","y":1975,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/524/515/","by":{"1":"30"}},{"t":"case","label":"United States v. Huet","cite":"665 F.3d 588","y":2012,"url":"https://www.courtlistener.com/c/F.3d/665/588/","by":{"1":"32"}},{"t":"case","label":"United States v. Jackson","cite":"120 F.3d 1226","y":1997,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/120/1226/","by":{"1":"7, 33"}},{"t":"case","label":"United States v. Kind","cite":"194 F.3d 900","y":1999,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/194/900/","by":{"1":"32"}},{"t":"case","label":"United States v. Lane","cite":"267 F.3d 715","y":2001,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/267/715/","by":{"1":"32"}},{"t":"case","label":"United States v. Miller","cite":"105 F.3d 552","y":1997,"url":"https://www.courtlistener.com/c/F.3d/105/552/","by":{"1":"32"}},{"t":"case","label":"United States v. Old Chief","cite":"56 F.3d 75","y":1995,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/56/75/","by":{"1":"26"}},{"t":"case","label":"United States v. Oliver","cite":"683 F.2d 224","y":1982,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/683/224/","by":{"1":"30"}},{"t":"case","label":"United States v. Rose","cite":"587 F.3d 695","y":2009,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/587/695/","by":{"1":"32"}},{"t":"case","label":"United States v. Smith","cite":"940 F.2d 710","y":1991,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/940/710/","by":{"1":"32"}},{"t":"case","label":"United States v. Thomas","cite":"615 F.3d 895","y":2010,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/615/895/","by":{"1":"32"}},{"t":"case","label":"United States v. Wiley","cite":"478 F.2d 415","y":1973,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/478/415/","by":{"1":"30"}},{"t":"case","label":"United States v. Williams","cite":"588 F.2d 92","y":1978,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/588/92/","by":{"1":"30"}},{"t":"case","label":"United States v. Williams","cite":"553 U.S. 285","y":2008,"id":"2007/06-694","sc":1,"by":{"1":"36"}},{"t":"case","label":"Utermehle v. Norment","cite":"197 U.S. 40","y":1905,"id":"scdb/1904-143","sc":1,"by":{"1":"35"}},{"t":"case","label":"Welch v. United States","cite":"136 S. Ct. 1257","y":2016,"id":"2015/15-6418","sc":1,"by":{"1":"42"}},{"t":"law","label":"Pub. L. No. 87-342","url":"https://www.govinfo.gov/link/statute/75/757","by":{"1":"30"}},{"t":"usc","label":"15 U.S.C. § 901","url":"https://www.law.cornell.edu/uscode/text/15/901","by":{"1":"29"}},{"t":"usc","label":"15 U.S.C. § 902","url":"https://www.law.cornell.edu/uscode/text/15/902","subs":["(d)"],"by":{"1":"29"}},{"t":"usc","label":"15 U.S.C. § 905","url":"https://www.law.cornell.edu/uscode/text/15/905","by":{"1":"29"}},{"t":"usc","label":"18 U.S.C. § 921","url":"https://www.law.cornell.edu/uscode/text/18/921","by":{"1":"30"}},{"t":"law","label":"and rules—Continued:, Pub. L. No. 99-408","url":"https://www.govinfo.gov/link/statute/100/920","by":{"1":"33"}},{"t":"law","label":"Pub. L. No. 99-570","url":"https://www.govinfo.gov/link/statute/100/3207","by":{"1":"33"}},{"t":"law","label":"Pub. L. No. 100-649","url":"https://www.govinfo.gov/link/statute/102/3816","by":{"1":"33"}},{"t":"law","label":"Pub. L. No. 100-690","url":"https://www.govinfo.gov/link/statute/102/4181","by":{"1":"19"}},{"t":"law","label":"Pub. L. No. 101-647","url":"https://www.govinfo.gov/link/statute/104/4829","by":{"1":"33"}},{"t":"law","label":"Pub. L. No. 103-159","url":"https://www.govinfo.gov/link/statute/107/1536","by":{"1":"33"}},{"t":"law","label":"Pub. L. No. 103-322","url":"https://www.govinfo.gov/link/statute/108/1973","by":{"1":"33"}},{"t":"law","label":"Pub. L. No. 104-208","url":"https://www.govinfo.gov/link/plaw/104/public/208","by":{"1":"33"}},{"t":"law","label":"Pub. L. No. 104-294","url":"https://www.govinfo.gov/link/plaw/104/public/294","by":{"1":"33"}},{"t":"law","label":"Pub. L. No. 105-277","url":"https://www.govinfo.gov/link/plaw/105/public/277","by":{"1":"33"}},{"t":"law","label":"Pub. L. No. 105-386","url":"https://www.govinfo.gov/link/plaw/105/public/386","by":{"1":"33"}},{"t":"law","label":"Pub. L. No. 107-273","url":"https://www.govinfo.gov/link/plaw/107/public/273","by":{"1":"33"}},{"t":"law","label":"Pub. L. No. 107-296","url":"https://www.govinfo.gov/link/plaw/107/public/296","by":{"1":"33"}},{"t":"law","label":"and rules—Continued:, Pub. L. No. 109-92","url":"https://www.govinfo.gov/link/plaw/109/public/92","by":{"1":"33"}},{"t":"law","label":"Pub. L. No. 109-304","url":"https://www.govinfo.gov/link/plaw/109/public/304","by":{"1":"33"}},{"t":"law","label":"Pub. L. No. 114-94","url":"https://www.govinfo.gov/link/plaw/114/public/94","by":{"1":"33"}},{"t":"law","label":"Pub. L. No. 115-391","url":"https://www.govinfo.gov/link/plaw/115/public/391","by":{"1":"33"}},{"t":"usc","label":"8 U.S.C. § 1182","url":"https://www.law.cornell.edu/uscode/text/8/1182","subs":["(a)(6)(C)(ii)"],"by":{"1":"25"}},{"t":"usc","label":"8 U.S.C. § 1184","url":"https://www.law.cornell.edu/uscode/text/8/1184","subs":["(a)(1)"],"stext":{"head":"§1184. Admission of nonimmigrants","paras":[[0,"(a) Regulations"],[0,"(1) The admission to the United States of any alien as a nonimmigrant shall be for such time and under such conditions as the Attorney General may by regulations prescribe, including when he deems necessary the giving of a bond with sufficient surety in such sum and containing such conditions as the Attorney General shall prescribe, to insure that at the expiration of such time or upon failure to maintain the status under which he was admitted, or to maintain any status subsequently acquired under section 1258 of this title, such alien will depart from the United States. No alien admitted to Guam or the Commonwealth of the Northern Mariana Islands without a visa pursuant to section 1182(l) of this title may be authorized to enter or stay in the United States other than in Guam or the Commonwealth of the Northern Mariana Islands or to remain in Guam or the Commonwealth of the Northern Mariana Islands for a period exceeding 45 days from date of admission to Guam or the Commonwealth of the Northern Mariana Islands. No alien admitted to the United States without a visa pursuant to section 1187 of this title may be authorized to remain in the United States as a nonimmigrant visitor for a period exceeding 90 days from the date of admission."],[0,"(2)(A) The period of authorized status as a nonimmigrant described in section 1101(a)(15)(O) of this title shall be for such period as the Attorney General may specify in order to provide for the event (or events) for which the nonimmigrant is admitted."],[0,"(B) The period of authorized status as a nonimmigrant described in section 1101(a)(15)(P) of this title shall be for such period as the Attorney General may specify in order to provide for the competition, event, or performance for which the nonimmigrant is admitted. In the case of nonimmigrants admitted as individual athletes under section 1101(a)(15)(P) of this title, the period of authorized status may be for an initial period (not to exceed 5 years) during which the nonimmigrant will perform as an athlete and such period may be extended by the Attorney General for an additional period of up to 5 years."],[0,"(b) Presumption of status; written waiver"],[0,"Every alien (other than a nonimmigrant described in subparagraph (L) or (V) of section 1101(a)(15) of this title, and other than a nonimmigrant described in any provision of section 1101(a)(15)(H)(i) of this title except subclause (b1) of such section) shall be presumed to be an immigrant until he establishes to the satisfaction of the consular officer, at the time of application for a visa, and the immigration officers, at the time of application for admission, that he is entitled to a nonimmigrant status under section 1101(a)(15) of this title. An alien who is an officer or employee of any foreign government or of any international organization entitled to enjoy privileges, exemptions, and immunities under the International Organizations Immunities Act [22 U.S.C. 288 et seq.], or an alien who is the attendant, servant, employee, or member of the immediate family of any such alien shall not be entitled to apply for or receive an immigrant visa, or to enter the United States as an immigrant unless he executes a written waiver in the same form and substance as is prescribed by section 1257(b) of this title."],[0,"(c) Petition of importing employer"],[0,"(1) The question of importing any alien as a nonimmigrant under subparagraph (H), (L), (O), or (P)(i) of section 1101(a)(15) of this title (excluding nonimmigrants under section 1101(a)(15)(H)(i)(b1) of this title) in any specific case or specific cases shall be determined by the Attorney General, after consultation with appropriate agencies of the Government, upon petition of the importing employer. Such petition, shall be made and approved before the visa is granted. The petition shall be in such form and contain such information as the Attorney General shall prescribe. The approval of such a petition shall not, of itself, be construed as establishing that the alien is a nonimmigrant. For purposes of this subsection with respect to nonimmigrants described in section 1101(a)(15)(H)(ii)(a) of this title, the term \"appropriate agencies of Government\" means the Department of Labor and includes the Department of Agriculture. The provisions of section 1188 of this title shall apply to the question of importing any alien as a nonimmigrant under section 1101(a)(15)(H)(ii)(a) of this title."],[0,"(2)(A) The Attorney General shall provide for a procedure under which an importing employer which meets requirements established by the Attorney General may file a blanket petition to import aliens as nonimmigrants described in section 1101(a)(15)(L) of this title instead of filing individual petitions under paragraph (1) to import such aliens. Such procedure shall permit the expedited processing of visas for admission of aliens covered under such a petition."],[0,"(B) For purposes of section 1101(a)(15)(L) of this title, an alien is considered to be serving in a capacity involving specialized knowledge with respect to a company if the alien has a special knowledge of the company product and its application in international markets or has an advanced level of knowledge of processes and procedures of the company."],[0,"(C) The Attorney General shall provide a process for reviewing and acting upon petitions under this subsection with respect to nonimmigrants described in section 1101(a)(15)(L) of this title within 30 days after the date a completed petition has been filed."],[0,"(D) The period of authorized admission for—"],[1,"(i) a nonimmigrant admitted to render services in a managerial or executive capacity under section 1101(a)(15)(L) of this title shall not exceed 7 years, or"],[1,"(ii) a nonimmigrant admitted to render services in a capacity that involves specialized knowledge under section 1101(a)(15)(L) of this title shall not exceed 5 years."],[0,"(E) In the case of an alien spouse admitted under section 1101(a)(15)(L) of this title, who is accompanying or following to join a principal alien admitted under such section, the Attorney General shall authorize the alien spouse to engage in employment in the United States and provide the spouse with an \"employment authorized\" endorsement or other appropriate work permit."],[0,"(F) An alien who will serve in a capacity involving specialized knowledge with respect to an employer for purposes of section 1101(a)(15)(L) of this title and will be stationed primarily at the worksite of an employer other than the petitioning employer or its affiliate, subsidiary, or parent shall not be eligible for classification under section 1101(a)(15)(L) of this title if—"],[1,"(i) the alien will be controlled and supervised principally by such unaffiliated employer; or"],[1,"(ii) the placement of the alien at the worksite of the unaffiliated employer is essentially an arrangement to provide labor for hire for the unaffiliated employer, rather than a placement in connection with the provision of a product or service for which specialized knowledge specific to the petitioning employer is necessary."],[0,"(3) The Attorney General shall approve a petition—"],[1,"(A) with respect to a nonimmigrant described in section 1101(a)(15)(O)(i) of this title only after consultation in accordance with paragraph (6) or, with respect to aliens seeking entry for a motion picture or television production, after consultation with the appropriate union representing the alien's occupational peers and a management organization in the area of the alien's ability, or"],[1,"(B) with respect to a nonimmigrant described in section 1101(a)(15)(O)(ii) of this title after consultation in accordance with paragraph (6) or, in the case of such an alien seeking entry for a motion picture or television production, after consultation with such a labor organization and a management organization in the area of the alien's ability."],[0,"In the case of an alien seeking entry for a motion picture or television production, (i) any opinion under the previous sentence shall only be advisory, (ii) any such opinion that recommends denial must be in writing, (iii) in making the decision the Attorney General shall consider the exigencies and scheduling of the production, and (iv) the Attorney General shall append to the decision any such opinion. The Attorney General shall provide by regulation for the waiver of the consultation requirement under subparagraph (A) in the case of aliens who have been admitted as nonimmigrants under section 1101(a)(15)(O)(i) of this title because of extraordinary ability in the arts and who seek readmission to perform similar services within 2 years after the date of a consultation under such subparagraph. Not later than 5 days after the date such a waiver is provided, the Attorney General shall forward a copy of the petition and all supporting documentation to the national office of an appropriate labor organization."],[0,"(4)(A) For purposes of section 1101(a)(15)(P)(i)(a) of this title, an alien is described in this subparagraph if the alien—"],[1,"(i)(I) performs as an athlete, individually or as part of a group or team, at an internationally recognized level of performance;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1184?type=usc&year=mostrecent&link-type=html"},"by":{"1":"24"},"q":[{"src":"brief","b":1,"text":"at the expiration of such time or upon failure to maintain the status under which he was admitted.","cite":"8 U.S.C. 1184(a)(1)"}]},{"t":"usc","label":"8 U.S.C. § 1185","url":"https://www.law.cornell.edu/uscode/text/8/1185","subs":["(a)(1)"],"by":{"1":"24"}},{"t":"usc","label":"8 U.S.C. § 1225","url":"https://www.law.cornell.edu/uscode/text/8/1225","subs":["(b)(2)(A)"],"stext":{"head":"§1225. Inspection by immigration officers; expedited removal of inadmissible arriving aliens; referral for hearing","paras":[[0,"(a) Inspection"],[0,"(1) Aliens treated as applicants for admission"],[1,"An alien present in the United States who has not been admitted or who arrives in the United States (whether or not at a designated port of arrival and including an alien who is brought to the United States after having been interdicted in international or United States waters) shall be deemed for purposes of this chapter an applicant for admission."],[0,"(2) Stowaways"],[1,"An arriving alien who is a stowaway is not eligible to apply for admission or to be admitted and shall be ordered removed upon inspection by an immigration officer. Upon such inspection if the alien indicates an intention to apply for asylum under section 1158 of this title or a fear of persecution, the officer shall refer the alien for an interview under subsection (b)(1)(B). A stowaway may apply for asylum only if the stowaway is found to have a credible fear of persecution under subsection (b)(1)(B). In no case may a stowaway be considered an applicant for admission or eligible for a hearing under section 1229a of this title."],[0,"(3) Inspection"],[1,"All aliens (including alien crewmen) who are applicants for admission or otherwise seeking admission or readmission to or transit through the United States shall be inspected by immigration officers."],[0,"(4) Withdrawal of application for admission"],[1,"An alien applying for admission may, in the discretion of the Attorney General and at any time, be permitted to withdraw the application for admission and depart immediately from the United States."],[0,"(5) Statements"],[1,"An applicant for admission may be required to state under oath any information sought by an immigration officer regarding the purposes and intentions of the applicant in seeking admission to the United States, including the applicant's intended length of stay and whether the applicant intends to remain permanently or become a United States citizen, and whether the applicant is inadmissible."],[0,"(b) Inspection of applicants for admission"],[0,"(1) Inspection of aliens arriving in the United States and certain other aliens who have not been admitted or paroled"],[0,"(A) Screening"],[0,"(i) In general"],[3,"If an immigration officer determines that an alien (other than an alien described in subparagraph (F)) who is arriving in the United States or is described in clause (iii) is inadmissible under section 1182(a)(6)(C) or 1182(a)(7) of this title, the officer shall order the alien removed from the United States without further hearing or review unless the alien indicates either an intention to apply for asylum under section 1158 of this title or a fear of persecution."],[0,"(ii) Claims for asylum"],[3,"If an immigration officer determines that an alien (other than an alien described in subparagraph (F)) who is arriving in the United States or is described in clause (iii) is inadmissible under section 1182(a)(6)(C) or 1182(a)(7) of this title and the alien indicates either an intention to apply for asylum under section 1158 of this title or a fear of persecution, the officer shall refer the alien for an interview by an asylum officer under subparagraph (B)."],[0,"(iii) Application to certain other aliens"],[0,"(I) In general"],[4,"The Attorney General may apply clauses (i) and (ii) of this subparagraph to any or all aliens described in subclause (II) as designated by the Attorney General. Such designation shall be in the sole and unreviewable discretion of the Attorney General and may be modified at any time."],[0,"(II) Aliens described"],[4,"An alien described in this clause is an alien who is not described in subparagraph (F), who has not been admitted or paroled into the United States, and who has not affirmatively shown, to the satisfaction of an immigration officer, that the alien has been physically present in the United States continuously for the 2-year period immediately prior to the date of the determination of inadmissibility under this subparagraph."],[0,"(B) Asylum interviews"],[0,"(i) Conduct by asylum officers"],[3,"An asylum officer shall conduct interviews of aliens referred under subparagraph (A)(ii), either at a port of entry or at such other place designated by the Attorney General."],[0,"(ii) Referral of certain aliens"],[3,"If the officer determines at the time of the interview that an alien has a credible fear of persecution (within the meaning of clause (v)), the alien shall be detained for further consideration of the application for asylum."],[0,"(iii) Removal without further review if no credible fear of persecution"],[0,"(I) In general"],[4,"Subject to subclause (III), if the officer determines that an alien does not have a credible fear of persecution, the officer shall order the alien removed from the United States without further hearing or review."],[0,"(II) Record of determination"],[4,"The officer shall prepare a written record of a determination under subclause (I). Such record shall include a summary of the material facts as stated by the applicant, such additional facts (if any) relied upon by the officer, and the officer's analysis of why, in the light of such facts, the alien has not established a credible fear of persecution. A copy of the officer's interview notes shall be attached to the written summary."],[0,"(III) Review of determination"],[4,"The Attorney General shall provide by regulation and upon the alien's request for prompt review by an immigration judge of a determination under subclause (I) that the alien does not have a credible fear of persecution. Such review shall include an opportunity for the alien to be heard and questioned by the immigration judge, either in person or by telephonic or video connection. Review shall be concluded as expeditiously as possible, to the maximum extent practicable within 24 hours, but in no case later than 7 days after the date of the determination under subclause (I)."],[0,"(IV) Mandatory detention"],[4,"Any alien subject to the procedures under this clause shall be detained pending a final determination of credible fear of persecution and, if found not to have such a fear, until removed."],[0,"(iv) Information about interviews"],[3,"The Attorney General shall provide information concerning the asylum interview described in this subparagraph to aliens who may be eligible. An alien who is eligible for such interview may consult with a person or persons of the alien's choosing prior to the interview or any review thereof, according to regulations prescribed by the Attorney General. Such consultation shall be at no expense to the Government and shall not unreasonably delay the process."],[0,"(v) \"Credible fear of persecution\" defined"],[3,"For purposes of this subparagraph, the term \"credible fear of persecution\" means that there is a significant possibility, taking into account the credibility of the statements made by the alien in support of the alien's claim and such other facts as are known to the officer, that the alien could establish eligibility for asylum under section 1158 of this title."],[0,"(C) Limitation on administrative review"],[2,"Except as provided in subparagraph (B)(iii)(III), a removal order entered in accordance with subparagraph (A)(i) or (B)(iii)(I) is not subject to administrative appeal, except that the Attorney General shall provide by regulation for prompt review of such an order under subparagraph (A)(i) against an alien who claims under oath, or as permitted under penalty of perjury under section 1746 of title 28, after having been warned of the penalties for falsely making such claim under such conditions, to have been lawfully admitted for permanent residence, to have been admitted as a refugee under section 1157 of this title, or to have been granted asylum under section 1158 of this title."],[0,"(D) Limit on collateral attacks"],[2,"In any action brought against an alien under section 1325(a) of this title or section 1326 of this title, the court shall not have jurisdiction to hear any claim attacking the validity of an order of removal entered under subparagraph (A)(i) or (B)(iii)."],[0,"(E) \"Asylum officer\" defined"],[2,"As used in this paragraph, the term \"asylum officer\" means an immigration officer who—"],[3,"(i) has had professional training in country conditions, asylum law, and interview techniques comparable to that provided to full-time adjudicators of applications under section 1158 of this title, and"],[3,"(ii) is supervised by an officer who meets the condition described in clause (i) and has had substantial experience adjudicating asylum applications."],[0,"(F) Exception"],[2,"Subparagraph (A) shall not apply to an alien who is a native or citizen of a country in the Western Hemisphere with whose government the United States does not have full diplomatic relations and who arrives by aircraft at a port of entry."],[0,"(G) Commonwealth of the Northern Mariana Islands"],[2,"Nothing in this subsection shall be construed to authorize or require any person described in section 1158(e) of this title to be permitted to apply for asylum under section 1158 of this title at any time before January 1, 2014."],[0,"(2) Inspection of other aliens"],[0,"(A) In general"],[2,"Subject to subparagraphs (B) and (C), in the case of an alien who is an applicant for admission, if the examining immigration officer determines that an alien seeking admission is not clearly and beyond a doubt entitled to be admitted, the alien shall be detained for a proceeding under section 1229a of this title."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1225?type=usc&year=mostrecent&link-type=html"},"by":{"1":"24"},"q":[{"src":"brief","b":1,"text":"clearly and beyond a doubt entitled to be admitted,","cite":"8 U.S.C. 1225(b)(2)(A)"}]},{"t":"usc","label":"8 U.S.C. § 1227","url":"https://www.law.cornell.edu/uscode/text/8/1227","subs":["(a)(1)(C)(i)","(a)(3)(D)"],"stext":{"head":"§1227. Deportable aliens","paras":[[0,"(a) Classes of deportable aliens"],[0,"Any alien (including an alien crewman) in and admitted to the United States shall, upon the order of the Attorney General, be removed if the alien is within one or more of the following classes of deportable aliens:"],[0,"(1) Inadmissible at time of entry or of adjustment of status or violates status"],[0,"(A) Inadmissible aliens"],[2,"Any alien who at the time of entry or adjustment of status was within one or more of the classes of aliens inadmissible by the law existing at such time is deportable."],[0,"(B) Present in violation of law"],[2,"Any alien who is present in the United States in violation of this chapter or any other law of the United States, or whose nonimmigrant visa (or other documentation authorizing admission into the United States as a nonimmigrant) has been revoked under section 1201(i) of this title, is deportable."],[0,"(C) Violated nonimmigrant status or condition of entry"],[0,"(i) Nonimmigrant status violators"],[3,"Any alien who was admitted as a nonimmigrant and who has failed to maintain the nonimmigrant status in which the alien was admitted or to which it was changed under section 1258 of this title, or to comply with the conditions of any such status, is deportable."],[0,"(ii) Violators of conditions of entry"],[3,"Any alien whom the Secretary of Health and Human Services certifies has failed to comply with terms, conditions, and controls that were imposed under section 1182(g) of this title is deportable."],[0,"(D) Termination of conditional permanent residence"],[0,"(i) In general"],[3,"Any alien with permanent resident status on a conditional basis under section 1186a of this title (relating to conditional permanent resident status for certain alien spouses and sons and daughters) or under section 1186b of this title (relating to conditional permanent resident status for certain alien entrepreneurs, spouses, and children) who has had such status terminated under such respective section is deportable."],[0,"(ii) Exception"],[3,"Clause (i) shall not apply in the cases described in section 1186a(c)(4) of this title (relating to certain hardship waivers)."],[0,"(E) Smuggling"],[0,"(i) In general"],[3,"Any alien who (prior to the date of entry, at the time of any entry, or within 5 years of the date of any entry) knowingly has encouraged, induced, assisted, abetted, or aided any other alien to enter or to try to enter the United States in violation of law is deportable."],[0,"(ii) Special rule in the case of family reunification"],[3,"Clause (i) shall not apply in the case of alien who is an eligible immigrant (as defined in section 301(b)(1) of the Immigration Act of 1990), was physically present in the United States on May 5, 1988, and is seeking admission as an immediate relative or under section 1153(a)(2) of this title (including under section 112 of the Immigration Act of 1990) or benefits under section 301(a) of the Immigration Act of 1990 if the alien, before May 5, 1988, has encouraged, induced, assisted, abetted, or aided only the alien's spouse, parent, son, or daughter (and no other individual) to enter the United States in violation of law."],[0,"(iii) Waiver authorized"],[3,"The Attorney General may, in his discretion for humanitarian purposes, to assure family unity, or when it is otherwise in the public interest, waive application of clause (i) in the case of any alien lawfully admitted for permanent residence if the alien has encouraged, induced, assisted, abetted, or aided only an individual who at the time of the offense was the alien's spouse, parent, son, or daughter (and no other individual) to enter the United States in violation of law."],[0,"(F) Repealed. Pub. L. 104–208, div. C, title VI, §671(d)(1)(C), Sept. 30, 1996, 110 Stat. 3009–723"],[0,"(G) Marriage fraud"],[2,"An alien shall be considered to be deportable as having procured a visa or other documentation by fraud (within the meaning of section 1182(a)(6)(C)(i) of this title) and to be in the United States in violation of this chapter (within the meaning of subparagraph (B)) if—"],[3,"(i) the alien obtains any admission into the United States with an immigrant visa or other documentation procured on the basis of a marriage entered into less than 2 years prior to such admission of the alien and which, within 2 years subsequent to any admission of the alien in the United States, shall be judicially annulled or terminated, unless the alien establishes to the satisfaction of the Attorney General that such marriage was not contracted for the purpose of evading any provisions of the immigration laws, or"],[3,"(ii) it appears to the satisfaction of the Attorney General that the alien has failed or refused to fulfill the alien's marital agreement which in the opinion of the Attorney General was made for the purpose of procuring the alien's admission as an immigrant."],[0,"(H) Waiver authorized for certain misrepresentations"],[2,"The provisions of this paragraph relating to the removal of aliens within the United States on the ground that they were inadmissible at the time of admission as aliens described in section 1182(a)(6)(C)(i) of this title, whether willful or innocent, may, in the discretion of the Attorney General, be waived for any alien (other than an alien described in paragraph (4)(D)) who—"],[3,"(i)(I) is the spouse, parent, son, or daughter of a citizen of the United States or of an alien lawfully admitted to the United States for permanent residence; and"],[3,"(II) was in possession of an immigrant visa or equivalent document and was otherwise admissible to the United States at the time of such admission except for those grounds of inadmissibility specified under paragraphs (5)(A) and (7)(A) of section 1182(a) of this title which were a direct result of that fraud or misrepresentation."],[3,"(ii) is a VAWA self-petitioner."],[2,"A waiver of removal for fraud or misrepresentation granted under this subparagraph shall also operate to waive removal based on the grounds of inadmissibility directly resulting from such fraud or misrepresentation."],[0,"(2) Criminal offenses"],[0,"(A) General crimes"],[0,"(i) Crimes of moral turpitude"],[3,"Any alien who—"],[4,"(I) is convicted of a crime involving moral turpitude committed within five years (or 10 years in the case of an alien provided lawful permanent resident status under section 1255(j) of this title) after the date of admission, and"],[4,"(II) is convicted of a crime for which a sentence of one year or longer may be imposed,"],[0,"is deportable."],[0,"(ii) Multiple criminal convictions"],[3,"Any alien who at any time after admission is convicted of two or more crimes involving moral turpitude, not arising out of a single scheme of criminal misconduct, regardless of whether confined therefor and regardless of whether the convictions were in a single trial, is deportable."],[0,"(iii) Aggravated felony"],[3,"Any alien who is convicted of an aggravated felony at any time after admission is deportable."],[0,"(iv) High speed flight"],[3,"Any alien who is convicted of a violation of section 758 of title 18 (relating to high speed flight from an immigration checkpoint) is deportable."],[0,"(v) Failure to register as a sex offender"],[3,"Any alien who is convicted under section 2250 of title 18 is deportable."],[0,"(vi) Waiver authorized"],[3,"Clauses (i), (ii), (iii), and (iv) shall not apply in the case of an alien with respect to a criminal conviction if the alien subsequent to the criminal conviction has been granted a full and unconditional pardon by the President of the United States or by the Governor of any of the several States."],[0,"(B) Controlled substances"],[0,"(i) Conviction"],[3,"Any alien who at any time after admission has been convicted of a violation of (or a conspiracy or attempt to violate) any law or regulation of a State, the United States, or a foreign country relating to a controlled substance (as defined in section 802 of title 21), other than a single offense involving possession for one's own use of 30 grams or less of marijuana, is deportable."],[0,"(ii) Drug abusers and addicts"],[3,"Any alien who is, or at any time after admission has been, a drug abuser or addict is deportable."],[0,"(C) Certain firearm offenses"],[2,"Any alien who at any time after admission is convicted under any law of purchasing, selling, offering for sale, exchanging, using, owning, possessing, or carrying, or of attempting or conspiring to purchase, sell, offer for sale, exchange, use, own, possess, or carry, any weapon, part, or accessory which is a firearm or destructive device (as defined in section 921(a) of title 18) in violation of any law is deportable."],[0,"(D) Miscellaneous crimes"],[2,"Any alien who at any time has been convicted (the judgment on such conviction becoming final) of, or has been so convicted of a conspiracy or attempt to violate—"],[3,"(i) any offense under chapter 37 (relating to espionage), chapter 105 (relating to sabotage), or chapter 115 (relating to treason and sedition) of title 18 for which a term of imprisonment of five or more years may be imposed;"],[3,"(ii) any offense under section 871 or 960 of title 18;"],[3,"(iii) a violation of any provision of the Military Selective Service Act (50 U.S.C. App. 451 et seq.) [now 50 U.S.C. 3801 et seq.] or the Trading With the Enemy Act (50 U.S.C. App. 1 et seq.) [now 50 U.S.C. 4301 et seq.]; or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1227?type=usc&year=mostrecent&link-type=html"},"by":{"1":"24, 25"},"q":[{"src":"brief","b":1,"text":"who was admitted as a nonimmigrant and who has failed to maintain the nonimmigrant status in which the alien was admitted,","cite":"8 U.S.C. 1227(a)(1)(C)(i)"}]},{"t":"usc","label":"8 U.S.C. § 1325","url":"https://www.law.cornell.edu/uscode/text/8/1325","subs":["(a)","(b)"],"by":{"1":"24, 24"}},{"t":"usc","label":"8 U.S.C. § 1361","url":"https://www.law.cornell.edu/uscode/text/8/1361","by":{"1":"24"}},{"t":"usc","label":"8 U.S.C. § 1611","url":"https://www.law.cornell.edu/uscode/text/8/1611","by":{"1":"25"}},{"t":"usc","label":"8 U.S.C. § 1621","url":"https://www.law.cornell.edu/uscode/text/8/1621","subs":["(a)","(c)(1)"],"by":{"1":"25, 25"}},{"t":"usc","label":"8 U.S.C. § 1641","url":"https://www.law.cornell.edu/uscode/text/8/1641","subs":["(b)"],"by":{"1":"25"}},{"t":"usc","label":"18 U.S.C. § 201","url":"https://www.law.cornell.edu/uscode/text/18/201","subs":["(b)(2)"],"by":{"1":"23"}},{"t":"usc","label":"18 U.S.C. § 611","url":"https://www.law.cornell.edu/uscode/text/18/611","subs":["(a)","(b)","(c)"],"by":{"1":"25, 25, 25"}},{"t":"usc","label":"18 U.S.C. § 1015","url":"https://www.law.cornell.edu/uscode/text/18/1015","by":{"1":"25"}},{"t":"usc","label":"18 U.S.C. § 1924","url":"https://www.law.cornell.edu/uscode/text/18/1924","subs":["(a)"],"by":{"1":"23"}},{"t":"usc","label":"18 U.S.C. § 2251","url":"https://www.law.cornell.edu/uscode/text/18/2251","subs":["(b)"],"by":{"1":"24"}},{"t":"usc","label":"21 U.S.C. § 861","url":"https://www.law.cornell.edu/uscode/text/21/861","subs":["(a)(2)","(b)","(c)"],"stext":{"head":"§861. Employment or use of persons under 18 years of age in drug operations","paras":[[0,"(a) Unlawful acts"],[0,"It shall be unlawful for any person at least eighteen years of age to knowingly and intentionally—"],[1,"(1) employ, hire, use, persuade, induce, entice, or coerce, a person under eighteen years of age to violate any provision of this subchapter or subchapter II;"],[1,"(2) employ, hire, use, persuade, induce, entice, or coerce, a person under eighteen years of age to assist in avoiding detection or apprehension for any offense of this subchapter or subchapter II by any Federal, State, or local law enforcement official; or"],[1,"(3) receive a controlled substance from a person under 18 years of age, other than an immediate family member, in violation of this subchapter or subchapter II."],[0,"(b) Penalty for first offense"],[0,"Any person who violates subsection (a) is subject to twice the maximum punishment otherwise authorized and at least twice any term of supervised release otherwise authorized for a first offense. Except to the extent a greater minimum sentence is otherwise provided, a term of imprisonment under this subsection shall not be less than one year."],[0,"(c) Penalty for subsequent offenses"],[0,"Any person who violates subsection (a) after a prior conviction under subsection (a) of this section has become final, is subject to three times the maximum punishment otherwise authorized and at least three times any term of supervised release otherwise authorized for a first offense. Except to the extent a greater minimum sentence is otherwise provided, a term of imprisonment under this subsection shall not be less than one year. Penalties for third and subsequent convictions shall be governed by section 841(b)(1)(A) of this title."],[0,"(d) Penalty for providing or distributing controlled substance to underage person"],[0,"Any person who violates subsection (a)(1) or (2) 1"],[1,"(1) by knowingly providing or distributing a controlled substance or a controlled substance analogue to any person under eighteen years of age; or"],[1,"(2) if the person employed, hired, or used is fourteen years of age or younger,"],[0,"shall be subject to a term of imprisonment for not more than five years or a fine of not more than $50,000, or both, in addition to any other punishment authorized by this section."],[0,"(e) Suspension of sentence; probation; parole"],[0,"In any case of any sentence imposed under this section, imposition or execution of such sentence shall not be suspended and probation shall not be granted. An individual convicted under this section of an offense for which a mandatory minimum term of imprisonment is applicable shall not be eligible for parole under section 4202 of title 18 2 until the individual has served the mandatory term of imprisonment as enhanced by this section."],[0,"(f) Distribution of controlled substance to pregnant individual"],[0,"Except as authorized by this subchapter, it shall be unlawful for any person to knowingly or intentionally provide or distribute any controlled substance to a pregnant individual in violation of any provision of this subchapter. Any person who violates this subsection shall be subject to the provisions of subsections (b), (c), and (e)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/861?type=usc&year=mostrecent&link-type=html"},"by":{"1":"23, 23, 23"},"q":[{"src":"opinion","who":"Justice Alito, dissenting","text":"officer, employee, contractor, or consultant of the United States [who] knowingly removes [classified] documents or materials without authority.","cite":"21 U. S. C. §861(a)"}]},{"t":"usc","label":"26 U.S.C. § 5845","url":"https://www.law.cornell.edu/uscode/text/26/5845","subs":["(a)(6)","(b)"],"by":{"1":"44, 44"}},{"t":"usc","label":"26 U.S.C. § 5861","url":"https://www.law.cornell.edu/uscode/text/26/5861","subs":["(d)"],"by":{"1":"44"}},{"t":"usc","label":"28 U.S.C. § 1864","url":"https://www.law.cornell.edu/uscode/text/28/1864","subs":["(a)"],"by":{"1":"24"}},{"t":"usc","label":"28 U.S.C. § 1865","url":"https://www.law.cornell.edu/uscode/text/28/1865","subs":["(a)","(b)(1)","(b)(5)"],"by":{"1":"24, 24, 24"}},{"t":"rule","label":"Fed. R. Crim. P. 11","url":"https://www.law.cornell.edu/rules/frcrmp/rule_11","subs":["(b)(1)(H)"],"by":{"1":"37"}},{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"by":{"2":"20"},"q":[{"src":"brief","b":2,"text":"It is impossible to assert with any degree of assurance that congressional failure to act represents affirmative congressional approval of the Court’s statutory interpretation.","cite":"532 U.S. 275, 292"}]},{"t":"case","label":"Arthur Andersen LLP v. United States","cite":"544 U.S. 696","y":2005,"id":"2004/04-368","sc":1,"by":{"2":"7, 8, 9"}},{"t":"case","label":"Ball v. United States","cite":"470 U.S. 856","y":1985,"id":"1984/84-5004","sc":1,"by":{"2":"4"},"q":[{"src":"brief","b":2,"text":"Congress does not create criminal offenses having no sentencing component.","cite":"470 U.S. 856, 861"}]},{"t":"case","label":"Descamps v. United States","cite":"570 U.S. 254","y":2013,"id":"2012/11-9540","sc":1,"by":{"2":"18"}},{"t":"case","label":"Hinck v. United States","cite":"550 U.S. 501","y":2007,"id":"2006/06-376","sc":1,"by":{"2":"6"}},{"t":"case","label":"Jones v. Liberty Glass Co.","cite":"332 U.S. 524","y":1947,"id":"scdb/1947-015","sc":1,"by":{"2":"20"}},{"t":"case","label":"McFadden v. United States","cite":"135 S. Ct. 2298","y":2015,"id":"2014/14-378","sc":1,"by":{"2":"1, 12, 19"}},{"t":"case","label":"Microsoft Corp. v. I4I Ltd. P’ship","cite":"564 U.S. 91","y":2011,"id":"2010/10-290","sc":1,"by":{"2":"6, 7"}},{"t":"case","label":"RadLAX Gateway Hotel, LLC v. Amalgamated Bank","cite":"566 U.S. 639","y":2012,"id":"2011/11-166","sc":1,"by":{"2":"6"}},{"t":"case","label":"United States v. Bridgeforth","cite":"441 F.3d 864","y":2006,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/441/864/","by":{"2":"17"}},{"t":"case","label":"United States v. Crooked Arm","cite":"853 F.3d 1065","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/853/1065/","by":{"2":"17"}},{"t":"case","label":"United States v. Wells","cite":"519 U.S. 482","y":1997,"id":"1996/95-1228","sc":1,"by":{"2":"4"}},{"t":"case","label":"United States v. Wilson","cite":"503 U.S. 333","y":1992,"id":"1991/90-1745","sc":1,"by":{"2":"18"},"q":[{"src":"brief","b":2,"text":"when Congress alters the words of a statute, it must intend to change the statute’s meaning.","cite":"503 U.S. 333, 336"}]},{"t":"case","label":"United States v. Yermian","cite":"468 U.S. 63","y":1984,"id":"1983/83-346","sc":1,"by":{"2":"3, 4"}},{"t":"usc","label":"18 U.S.C. § 1001","url":"https://www.law.cornell.edu/uscode/text/18/1001","by":{"2":"10"}},{"t":"usc","label":"18 U.S.C. § 1512","url":"https://www.law.cornell.edu/uscode/text/18/1512","subs":["(b)(2)"],"by":{"2":"8"}},{"t":"rule","label":"Fed. R. Evid. 403","url":"https://www.law.cornell.edu/rules/fre/rule_403","by":{"2":"14"}}]};